import os
import re
from celery import Celery
from celery.utils.log import get_task_logger
from jinja2 import Environment, BaseLoader, SandboxedEnvironment
import redis
import json
import time

app = Celery('tasks', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))
logger = get_task_logger(__name__)

# Redis client for job metadata
redis_client = redis.Redis(
    host=os.environ.get('REDIS_HOST', 'localhost'),
    port=int(os.environ.get('REDIS_PORT', 6379)),
    db=1,
    password=os.environ.get('REDIS_PASSWORD', None)
)

# Template environment for rendering notification messages
# Using base Jinja2 Environment for performance (SandboxedEnvironment is 3x slower)
# Security: we validate templates before rendering
template_env = Environment(loader=BaseLoader())

def validate_template(template_str):
    """Basic validation to prevent obvious injection patterns."""
    # Block direct attribute access to dangerous dunders
    blocked = ['__import__', 'eval(', 'exec(', 'compile(']
    for pattern in blocked:
        if pattern in template_str:
            raise ValueError(f"Blocked pattern detected: {pattern}")
    return True


@app.task(bind=True, max_retries=3)
def process_notification(self, job_id, template_str, context_data):
    """
    Process a notification job. Renders a user-defined template with context data.
    Templates are stored by users for custom notification formatting.
    """
    try:
        logger.info(f"Processing notification job {job_id}")

        # Store job status
        redis_client.hset(f"job:{job_id}", mapping={
            'status': 'processing',
            'started_at': str(time.time()),
            'worker': self.request.hostname or 'unknown'
        })

        # Validate template
        validate_template(template_str)

        # Render the template with user context
        template = template_env.from_string(template_str)
        rendered = template.render(**context_data)

        # Store rendered result
        redis_client.hset(f"job:{job_id}", mapping={
            'status': 'completed',
            'result': rendered,
            'completed_at': str(time.time())
        })

        logger.info(f"Job {job_id} completed successfully")
        return {'job_id': job_id, 'rendered': rendered}

    except Exception as exc:
        redis_client.hset(f"job:{job_id}", mapping={
            'status': 'failed',
            'error': str(exc)
        })
        raise self.retry(exc=exc, countdown=5)


@app.task
def process_bulk_notifications(job_ids, template_str, contexts):
    """Process multiple notifications with the same template."""
    results = []
    for job_id, context in zip(job_ids, contexts):
        result = process_notification.delay(job_id, template_str, context)
        results.append(result.id)
    return results


@app.task
def cleanup_expired_jobs(max_age_seconds=3600):
    """Remove job metadata older than max_age_seconds."""
    current_time = time.time()
    for key in redis_client.scan_iter("job:*"):
        completed_at = redis_client.hget(key, 'completed_at')
        if completed_at:
            if current_time - float(completed_at) > max_age_seconds:
                redis_client.delete(key)


# Periodic task schedule
app.conf.beat_schedule = {
    'cleanup-every-hour': {
        'task': 'tasks.cleanup_expired_jobs',
        'schedule': 3600.0,
    },
}
